import os

from openai import OpenAI

# Ollama 的 OpenAI 相容端點：本機是 http://localhost:11434/v1，
# Ollama 自己的雲端是 https://ollama.com/v1（官方文件的 Base URLs 表）。
LOCAL_BASE_URL = "http://localhost:11434/v1"
CLOUD_BASE_URL = "https://ollama.com/v1"


def get_client(target: str) -> OpenAI:
  """target 是 'local' 或 'cloud'，換的只有 base_url 和金鑰。"""
  if target == "local":
    # 本機不檢查金鑰，用戶端仍要求填一個值，官方範例填 'ollama'。
    return OpenAI(base_url=LOCAL_BASE_URL, api_key="ollama")
  if target == "cloud":
    # 雲端要求真正的金鑰，一律從環境變數讀，不寫進程式。
    return OpenAI(base_url=CLOUD_BASE_URL, api_key=os.environ["OLLAMA_API_KEY"])
  raise ValueError(f"unknown target: {target}")


def ask(target: str, model: str, prompt: str) -> str:
  client = get_client(target)
  response = client.chat.completions.create(
    model=model,
    messages=[{"role": "user", "content": prompt}],
    timeout=30,
  )
  return response.choices[0].message.content


if __name__ == "__main__":
  # 本機模型只留在自己的機器上執行。
  print(ask("local", "gpt-oss:20b", "用一句話說明什麼是去識別化"))
